pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(0x123);
        c.addReward(rewardToken);

        address newOwner = address(0x456);

        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success, "Reference succeeds, mutant should revert");
    }
}
